function create_evil(__k: LevelApi): void {
  const { world, KikiPos, KColor, KikiFace, KVector, KQuaternion, continuous, once, range, pmod, pyStr, applyColorScheme, kikiObjectToGate, kikiObjectToSwitch } = __k;
  const { KikiBomb, KikiCellText, KikiGate, KikiGear, KikiGenerator, KikiLight, KikiMotorCylinder, KikiMotorGear, KikiMutant, KikiSpikes, KikiStone, KikiSwitch, KikiValve, KikiWall, KikiWire, KikiWireStone } = __k;
  void [world, KikiPos, KColor, KikiFace, KVector, KQuaternion, continuous, once, range, pmod, pyStr, applyColorScheme, kikiObjectToGate, kikiObjectToSwitch];
  void [KikiBomb, KikiCellText, KikiGate, KikiGear, KikiGenerator, KikiLight, KikiMotorCylinder, KikiMotorGear, KikiMutant, KikiSpikes, KikiStone, KikiSwitch, KikiValve, KikiWall, KikiWire, KikiWireStone];
  let sx: any, sy: any, sz: any, z: any, x: any;
  [sx, sy, sz] = [13, 5, 13];
  for (z of range((Math.floor((-sz) / 2)) + 2, Math.floor(sz / 2))) {
    world.addObjectAtPos(new KikiWall(), world.decenter((Math.floor((-sx) / 2)) + 2, 0, z));
    world.addObjectAtPos(new KikiWall(), world.decenter((Math.floor(sx / 2)) - 1, 0, z));
  }
  for (z of range((Math.floor((-sz) / 2)) + 4, (Math.floor(sz / 2)) - 2)) {
    world.addObjectAtPos(new KikiWall(), world.decenter((Math.floor((-sx) / 2)) + 4, 0, z));
    world.addObjectAtPos(new KikiWall(), world.decenter((Math.floor(sx / 2)) - 3, 0, z));
  }
  for (x of range((Math.floor((-sx) / 2)) + 3, (Math.floor(sx / 2)) - 1)) {
    world.addObjectAtPos(new KikiWall(), world.decenter(x, 0, (Math.floor((-sz) / 2)) + 2));
    world.addObjectAtPos(new KikiWall(), world.decenter(x, 0, (Math.floor(sz / 2)) - 1));
  }
  for (x of range((Math.floor((-sx) / 2)) + 4, (Math.floor(sx / 2)) - 2)) {
    world.addObjectAtPos(new KikiWall(), world.decenter(x, 0, (Math.floor((-sz) / 2)) + 4));
    world.addObjectAtPos(new KikiWall(), world.decenter(x, 0, (Math.floor(sz / 2)) - 3));
  }
  world.addObjectAtPos(new KikiGenerator(KikiFace.PY), world.decenter(0, 0, -4));
  world.addObjectAtPos(new KikiWireStone(), world.decenter(4, 0, 0));
  world.addObjectAtPos(new KikiWireStone(), world.decenter(-4, 0, 0));
  world.addObjectAtPos(new KikiWireStone(), world.decenter(0, -2, -2));
  world.addObjectAtPos(new KikiWireStone(), world.decenter(0, -1, -2));
  world.addObjectAtPos(new KikiMotorGear(KikiFace.PY), world.decenter(0, 0, -2));
  world.addObjectAtPos(new KikiMotorCylinder(KikiFace.PY), world.decenter(0, 1, -2));
  world.addObjectAtPos(new KikiBomb(), world.decenter(0, 2, -2));
  world.addObjectAtPos(new KikiBomb(), world.decenter(1, 0, -2));
  world.addObjectAtPos(new KikiBomb(), world.decenter(-1, 0, -2));
  world.removeObject(world.getOccupantAtPos(world.decenter(0, 0, 3)));
  world.addObjectAtPos(new KikiWireStone(), world.decenter(0, 0, 3));
  void [sx, sy, sz, z, x];
}

