function create_mutants(__k: LevelApi): void {
  const { world, KikiPos, KColor, KikiFace, KVector, KQuaternion, continuous, once, range, pmod, pyStr, applyColorScheme, kikiObjectToGate, kikiObjectToSwitch } = __k;
  const { KikiBomb, KikiCellText, KikiGate, KikiGear, KikiGenerator, KikiLight, KikiMotorCylinder, KikiMotorGear, KikiMutant, KikiSpikes, KikiStone, KikiSwitch, KikiValve, KikiWall, KikiWire, KikiWireStone } = __k;
  void [world, KikiPos, KColor, KikiFace, KVector, KQuaternion, continuous, once, range, pmod, pyStr, applyColorScheme, kikiObjectToGate, kikiObjectToSwitch];
  void [KikiBomb, KikiCellText, KikiGate, KikiGear, KikiGenerator, KikiLight, KikiMotorCylinder, KikiMotorGear, KikiMutant, KikiSpikes, KikiStone, KikiSwitch, KikiValve, KikiWall, KikiWire, KikiWireStone];
  let s: any, i: any, mutant: any;
  s = world.getSize();
  world.addObjectLine(() => new KikiWall(), [2, 2, 2], [s.x - 3, 2, 2]);
  world.addObjectLine(() => new KikiWall(), [s.x - 3, 2, 2], [s.x - 3, s.y - 3, 2]);
  world.addObjectLine(() => new KikiWall(), [s.x - 3, s.y - 3, 2], [s.x - 3, s.y - 3, s.z - 3]);
  world.addObjectLine(() => new KikiWall(), [s.x - 3, s.y - 3, s.z - 3], [2, s.y - 3, s.z - 3]);
  world.addObjectLine(() => new KikiWall(), [2, s.y - 3, s.z - 3], [2, 2, s.z - 3]);
  world.addObjectLine(() => new KikiWall(), [2, 2, s.z - 3], [2, 2, 2]);
  world.v.num_mutants = 5;
  world.v.death_counter = 0;
  function botDied(): any {
    world.v.death_counter += 1;
    if (world.v.death_counter >= world.v.num_mutants) {
      world.activate("exit");
    }
  }
  void botDied;
  for (i of range(world.v.num_mutants)) {
    mutant = new KikiMutant();
    mutant.getEventWithName("died").addAction(once(botDied));
    world.setObjectRandom(mutant);
  }
  void [s, i, mutant];
}

